contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint _minSum, uint _minSum2) public {
        c.SetMinSum(_minSum); if (__ESBMC_reverted()) return;
        bool preOk = (c.MinSum() == _minSum);

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.SetMinSum(_minSum2); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(preOk && reverted && c.MinSum() == _minSum);
    }
}

