// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 _minSum, uint256 _minSum2) internal {
        try c.SetMinSum(_minSum) {} catch { return; }
        bool preOk = (c.MinSum() == _minSum);
        try c.Initialized() {} catch { return; }
        bool reverted;
        try c.SetMinSum(_minSum2) { reverted = false; } catch { reverted = true; }
        assertTrue(preOk && reverted && c.MinSum() == _minSum);
    }

    function testFuzz_run(uint256 _minSum, uint256 _minSum2) public {
        _run(_minSum, _minSum2);
    }

    receive() external payable {}
}
